import{_ as t,c as o,o as a,ae as r}from"./chunks/framework.Cd-3tpCq.js";const m=JSON.parse('{"title":"Get Compare Item","description":"","frontmatter":{"outline":false,"examples":[{"id":"get-compare-item","title":"Get Single Compare Item","description":"Retrieve a specific compare item by its ID.","request":"GET /api/shop/compare_items/37\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer <accessToken>\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 155,\\n  \\"createdAt\\": \\"2026-08-07T15:56:42+05:30\\",\\n  \\"updatedAt\\": \\"2026-08-07T15:56:42+05:30\\",\\n  \\"product\\": \\"/api/shop/products/126\\",\\n  \\"customer\\": \\"/api/shop/customers/122\\"\\n}\\n","commonErrors":[{"error":"404 Not Found — Compare item not found","cause":"No such row, or it belongs to another customer","solution":"Use an ID returned by Get Compare Items for this customer"},{"error":"403 Forbidden","cause":"No customer Bearer token was sent","solution":"Log the customer in; guests hold no comparison list"}]}]},"headers":[],"relativePath":"api/rest-api/shop/compare/get.md","filePath":"api/rest-api/shop/compare/get.md"}'),s={name:"api/rest-api/shop/compare/get.md"};function d(i,e,n,c,p,h){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="get-compare-item" tabindex="-1">Get Compare Item <a class="header-anchor" href="#get-compare-item" aria-label="Permalink to &quot;Get Compare Item&quot;">​</a></h1><p>Retrieve a single compare item by ID.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/compare_items/{id}</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Customer Bearer token (<code>Bearer &lt;accessToken&gt;</code>)</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path Parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Yes</td><td>Compare item ID</td></tr></tbody></table><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><p>One comparison row, with product and customer as <strong>path references, not nested objects</strong>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Comparison row ID.</td></tr><tr><td><code>product</code></td><td>string</td><td>Path of the compared product, e.g. <code>/api/shop/products/126</code>.</td></tr><tr><td><code>customer</code></td><td>string</td><td>Path of the owning customer.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>ISO 8601 timestamps.</td></tr></tbody></table><p>A row belonging to another customer answers <code>404</code>, the same as an ID that does not exist.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Confirm a row still exists</strong> — before offering &quot;remove&quot;, check the ID rather than reacting to a <code>404</code> mid-action.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Prefer the list endpoint</strong> — this returns the same four fields for one row, so fetching the whole list is usually one call instead of many.</li><li><strong>Read <code>404</code> as &quot;not yours or not there&quot;</strong> — the endpoint gives no separate signal for another customer&#39;s row.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/compare/list.html">Get Compare Items</a> — the customer&#39;s comparison rows</li><li><a href="/api/rest-api/shop/compare/create.html">Create Compare Item</a> — add a product to the comparison list</li><li><a href="/api/rest-api/shop/compare/delete.html">Delete Compare Item</a> — remove one comparison row</li></ul>',18)]))}const u=t(s,[["render",d]]);export{m as __pageData,u as default};
